5 15:08:44", "", "GRM", "GRM00008", "I", "Duplicate data(Origin : {0} / Destination : {1})", "NPADM", "2019-05-14 15:48:32", "NPADM", "2019-05-15 14:32:26", "", "GRM", "GRM00009", "E", "{0} already exists. ", "NPADM", "2019-05-15 14:01:20", "NPADM", "2019-05-15 14:09:31", "", "DND", "DND00003", "W", "Two Currency does exist. You can not discount in amount.", "NPADM", "2019-05-15 13:36:12", "NPADM", "2019-05-15 13:36:25"]);
